"""Equivalence with R, case by case, on 142 tables generated by
validation/generate_r_reference.R (random tables of 14 shapes and three
sparsity levels, tables with single-observation strata, and textbook examples).
"""

import json
import warnings

import numpy as np
import pytest

import cmhstats
from conftest import FIXTURES, close, r_array

with open(FIXTURES / "r_reference.json") as fh:
    CASES = json.load(fh)["cases"]

KEYMAP = {"cor": "correlation", "rmeans": "row_mean_scores", "general": "general_association"}


def ids(case):
    return case["name"]


def py_table(case):
    if case["family"] == "single_obs":
        return r_array(case["full_counts"], case["full_dim"])
    return r_array(case["counts"], case["dim"])


def run_cmh(case, scores):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        return cmhstats.cmh_test(py_table(case), scores=scores)


def assert_matches(res, ref_rows):
    for rkey, pykey in KEYMAP.items():
        if rkey not in ref_rows:
            continue
        stat = getattr(res, pykey)
        ref = ref_rows[rkey]
        assert stat.df == ref["df"], (pykey, stat.df, ref["df"])
        assert close(stat.statistic, ref["chisq"]), (pykey, stat.statistic, ref["chisq"])
        assert close(stat.pvalue, ref["p"]), (pykey, stat.pvalue, ref["p"])


@pytest.mark.parametrize("scores", ["table", "rank", "ridit", "modridit"])
@pytest.mark.parametrize("case", CASES, ids=ids)
def test_three_statistics_match_r_pooled_formula(case, scores):
    """All three statistics, all four score types, against vcdExtra's formulas in R."""
    ref = case["r_pooled"][scores]
    res = run_cmh(case, scores)
    assert set(ref) == {"cor", "rmeans", "general"}
    # where R's solve() fails the pooled matrix is singular; both return NaN
    assert_matches(res, ref)


@pytest.mark.parametrize("case", [c for c in CASES if c.get("vcd_table")], ids=ids)
def test_matches_vcdextra_cmhtest(case):
    assert_matches(run_cmh(case, "table"), case["vcd_table"])
    if case.get("vcd_modridit"):
        assert_matches(run_cmh(case, "modridit"), case["vcd_modridit"])


@pytest.mark.parametrize("case", [c for c in CASES if c.get("mantelhaen_nocorrect")], ids=ids)
def test_general_association_matches_mantelhaen_test(case):
    ref = case["mantelhaen_nocorrect"]
    res = run_cmh(case, "table").general_association
    assert res.df == ref["df"]
    assert close(res.statistic, ref["statistic"])
    assert close(res.pvalue, ref["p"])


@pytest.mark.parametrize("case", [c for c in CASES if c.get("coin_general")], ids=ids)
def test_general_association_matches_coin(case):
    ref = case["coin_general"]
    res = run_cmh(case, "table").general_association
    if np.isnan(res.statistic):
        # coin uses a Moore-Penrose inverse with reduced df where SAS reports missing
        pytest.skip("singular covariance: coin and SAS use different conventions")
    assert close(res.statistic, ref["statistic"])
    assert close(res.pvalue, ref["p"], rel=1e-6)


R_COMPATIBLE = [c for c in CASES if c.get("mantelhaen_nocorrect") and c["family"] != "single_obs"]


@pytest.mark.parametrize("case", R_COMPATIBLE, ids=ids)
def test_mantelhaen_test_port(case):
    """cmhstats.mantelhaen_test reproduces stats::mantelhaen.test, options included."""
    x = r_array(case["counts"], case["dim"])
    ref = case["mantelhaen_nocorrect"]
    res = cmhstats.mantelhaen_test(x, correct=False)
    assert res.df == ref["df"]
    assert close(res.statistic, ref["statistic"])
    assert close(res.pvalue, ref["p"])
    if "estimate" in ref:
        assert close(res.estimate, ref["estimate"])
        assert close(res.conf_int[0], ref["conf_int"][0])
        assert close(res.conf_int[1], ref["conf_int"][1])
    if "mantelhaen_correct" in case:
        corr = cmhstats.mantelhaen_test(x)  # R default: correct = TRUE
        assert close(corr.statistic, case["mantelhaen_correct"]["statistic"])
        assert close(corr.pvalue, case["mantelhaen_correct"]["p"])
    for alt in ("less", "greater"):
        key = f"mantelhaen_{alt}"
        if key in case:
            r = cmhstats.mantelhaen_test(x, alternative=alt)
            assert close(r.pvalue, case[key]["p"])
            for got, want in zip(r.conf_int, case[key]["conf_int"]):
                assert close(got, want)


@pytest.mark.parametrize("case", [c for c in CASES if c["family"] == "single_obs"], ids=ids)
def test_single_observation_strata_are_skipped(case):
    """R refuses these tables; cmhstats skips the n = 1 stratum and matches R
    run on the table without it."""
    full = py_table(case)
    with pytest.raises(ValueError, match="sample size in each stratum"):
        cmhstats.mantelhaen_test(full)
    res = run_cmh(case, "table")
    assert len(res.strata_excluded) >= 1
    assert_matches(res, case["r_pooled"]["table"])


TWO_BY_TWO = [c for c in CASES if c["dim"][:2] == [2, 2]]


def _check_estimate(est, ref):
    assert close(est.value, ref[0]), (est, ref)
    assert close(est.lower, ref[1]), (est, ref)
    assert close(est.upper, ref[2]), (est, ref)


@pytest.mark.parametrize("case", [c for c in TWO_BY_TWO if c.get("epir")], ids=ids)
def test_mh_estimates_and_breslow_day_match_epir(case):
    res = run_cmh(case, "table")
    ep = case["epir"]
    _check_estimate(res.common_odds_ratio[0], ep["or_mh"])
    _check_estimate(res.relative_risk_col1[0], ep["rr1_mh"])
    if "rr2_mh" in ep:
        _check_estimate(res.relative_risk_col2[0], ep["rr2_mh"])
    bd = ep["breslow_day"]
    assert res.breslow_day.df == bd["df"]
    assert close(res.breslow_day.statistic, bd["chisq"], rel=1e-7)
    assert close(res.breslow_day.pvalue, bd["p"], rel=1e-7)


@pytest.mark.parametrize("case", [c for c in TWO_BY_TWO if c.get("handwritten")], ids=ids)
def test_logit_estimators_and_tarone(case):
    res = run_cmh(case, "table")
    hw = case["handwritten"]
    logit = case.get("handwritten_full", hw)
    _check_estimate(res.common_odds_ratio[1], logit["or_logit"])
    _check_estimate(res.relative_risk_col1[1], logit["rr1_logit"])
    _check_estimate(res.relative_risk_col2[1], logit["rr2_logit"])
    for key, got in (("breslow_day", res.breslow_day), ("breslow_day_tarone", res.breslow_day_tarone)):
        ref = hw.get(key)
        if not ref or ref["df"] < 1 or ref["chisq"] == "NaN":
            # undefined: fewer than two usable strata, or a zero/infinite MH odds ratio
            assert got is None
            continue
        assert got.df == ref["df"]
        assert close(got.statistic, ref["chisq"], rel=1e-7, abs_=1e-9)


def test_sexualfun_single_stratum(r_reference):
    named = [c for c in r_reference["cases"] if "sexualfun_single_stratum" in c][0]
    sf = named["sexualfun_single_stratum"]
    res = cmhstats.cmh_test(r_array(sf["counts"], (4, 4)))
    assert_matches(res, sf["vcd_table"])


def test_reference_suite_is_not_trivially_small():
    assert len(CASES) >= 140
    assert sum(c["family"] == "single_obs" for c in CASES) >= 10
    assert len(TWO_BY_TWO) >= 30
